-- title that is not in a given database is simply skipped.
UPDATE entry SET title_be = COALESCE(title_be, 'Школа пад прыкрыццём'), overview_be = COALESCE(overview_be, 'Найлепшага агента Нацыянальнай службы разведкі Чон Хэ Сона паніжаюць на пасадзе пасля правалу задання. Пад прыкрыццём ён трапляе ў старэйшую школу, каб знайсці зніклае золата караля Каджона, і сустракае там настаўніцу О Су А, якая бачыць у ім сваё страчанае першае каханне, — і гэта вярэдзіць старыя душэўныя раны.') WHERE media_type = 'TV' AND tmdb_id = 248244;
UPDATE entry SET title_be = COALESCE(title_be, 'Суддзя з пекла'), overview_be = COALESCE(overview_be, 'Жорсткая і бязлітасная суддзя, якая карыстаецца ўладай толькі дзеля сябе, сустракае цёплага і жыццярадаснага дэтэктыва, для якога на першым месцы — ахвяры.') WHERE media_type = 'TV' AND tmdb_id = 235577;
UPDATE entry SET title_be = COALESCE(title_be, 'Афіцэр з чорным поясам'), overview_be = COALESCE(overview_be, 'Таленавіты майстар баявых мастацтваў, які не можа прайсці міма чалавека ў бядзе, аб''ядноўваецца з супрацоўнікам службы прабацыі, каб у якасці афіцэра па баявых мастацтвах змагацца са злачыннасцю і прадухіляць яе.') WHERE media_type = 'MOVIE' AND tmdb_id = 1139817;
UPDATE entry SET title_be = COALESCE(title_be, 'Гангстар вяртаецца ў школу'), overview_be = COALESCE(overview_be, 'Дух гангстара, які калісьці кінуў сярэднюю школу, выпадкова ўсяляецца ў цела 18-гадовага хлопца, што скончыў жыццё самагубствам. Ён вяртаецца ў школу, каб з дапамогай сваіх бандыцкіх навыкаў адпомсціць крыўдзіцелям, і нечакана знаходзіць там блізкіх людзей.') WHERE media_type = 'TV' AND tmdb_id = 224030;
UPDATE entry SET title_be = COALESCE(title_be, 'Крама для кілераў'), overview_be = COALESCE(overview_be, 'Пляменніца, якая страціла бацькоў і вырасла на руках у дзядзькі — уладальніка інтэрнэт-крамы, — пасля яго раптоўнай смерці адкрывае для сябе новую праўду.') WHERE media_type = 'TV' AND tmdb_id = 215072;
UPDATE entry SET title_be = COALESCE(title_be, 'Мой дэман'), overview_be = COALESCE(overview_be, 'Бязлітасны дэман страчвае свае сілы пасля таго, як лёс зводзіць яго з халоднай спадчынніцай, якая, магчыма, трымае ключ да яго страчаных здольнасцей — і да яго сэрца.') WHERE media_type = 'TV' AND tmdb_id = 218539;
UPDATE entry SET title_be = COALESCE(title_be, 'Гульня смерці'), overview_be = COALESCE(overview_be, 'На парозе пекла І Джэ павінен прайсці праз дванаццаць розных жыццяў і дванаццаць розных смерцяў у гэтай драме пра перараджэнне.') WHERE media_type = 'TV' AND tmdb_id = 218230;
UPDATE entry SET title_be = COALESCE(title_be, 'Мсцівец'), overview_be = COALESCE(overview_be, 'Кім Джы Ён вядзе падвойнае жыццё: удзень ён студэнт Карэйскага нацыянальнага паліцэйскага ўніверсітэта, а ўначы — Мсцівец, які ўласнаручна карае злачынцаў, што пазбеглі закону. Вакол яго — людзі, і ў кожнага з іх свае схаваныя матывы.') WHERE media_type = 'TV' AND tmdb_id = 205082;
UPDATE entry SET title_be = COALESCE(title_be, 'Балерына'), overview_be = COALESCE(overview_be, 'Смуткуючы па найлепшай сяброўцы, якую не здолела абараніць, былая целаахоўніца бярэцца выканаць яе апошняе жаданне — салодкую помсту.') WHERE media_type = 'MOVIE' AND tmdb_id = 961268;
UPDATE entry SET title_be = COALESCE(title_be, 'Ваенны пракурор Даберман'), overview_be = COALESCE(overview_be, 'Ваенны пракурор, які марыць пра ўладу і багацце, бачыць, як яго планы руйнуе непахісная навенькая, у якой ёсць уласныя мэты.') WHERE media_type = 'TV' AND tmdb_id = 135652;
UPDATE entry SET title_be = COALESCE(title_be, 'Калі жыццё дае табе мандарыны'), overview_be = COALESCE(overview_be, 'На востраве Чэджу гісторыя жвавай дзяўчыны і надзейнага хлопца перарастае ў аповед даўжынёй у жыццё — пра няўдачы і перамогі — і даказвае, што каханне не падуладнае часу.') WHERE media_type = 'TV' AND tmdb_id = 219246;
UPDATE entry SET title_be = COALESCE(title_be, 'Смачна есці, Ваша Вялікасць'), overview_be = COALESCE(overview_be, 'Перанёсшыся ў часе ў эпоху Часон, таленавітая шэф-кухарка сустракае караля-тырана. Яе сучасныя стравы зачароўваюць яго густ, але наперадзе яе чакаюць каралеўскія выпрабаванні.') WHERE media_type = 'TV' AND tmdb_id = 280945;
UPDATE entry SET title_be = COALESCE(title_be, 'Добры хлопец'), overview_be = COALESCE(overview_be, 'Алімпійскія медалісты ідуць у паліцыю па спецыяльнай праграме набору: яны мяняюць медалі на жэтоны і з дапамогай спартыўных навыкаў змагаюцца з жорсткімі злачынствамі і несправядлівасцю.') WHERE media_type = 'TV' AND tmdb_id = 231280;
UPDATE entry SET title_be = COALESCE(title_be, 'Разблытанае каханне'), overview_be = COALESCE(overview_be, 'Закаханая школьніца збіраецца заваяваць сэрца школьнага прыгажуна, выпрастаўшы свае кучаравыя валасы, — пакуль новы вучань, які перавёўся ў школу, не мяняе ўсё.') WHERE media_type = 'MOVIE' AND tmdb_id = 1355666;
UPDATE entry SET title_be = COALESCE(title_be, 'Вучэбная група'), overview_be = COALESCE(overview_be, 'Вучань найгоршай старэйшай школы Карэі, якому вучоба даецца цяжка, стварае вучэбную групу і адначасова абараняе аднакласнікаў сваім уменнем біцца — у надзеі адолець цяжкасці ў вучобе і паступіць ва ўніверсітэт.') WHERE media_type = 'TV' AND tmdb_id = 233347;
UPDATE entry SET title_be = COALESCE(title_be, 'Сям''я па выбары'), overview_be = COALESCE(overview_be, 'Маладзёжная рамантычная гісторыя пра двух хлопцаў і дзяўчыну, якія не былі сваякамі па крыві, але ў юнацтве ставіліся адно да аднаго як да сям''і, — і пра тое, як яны сустракаюцца зноў праз 10 гадоў.') WHERE media_type = 'TV' AND tmdb_id = 237565;
UPDATE entry SET title_be = COALESCE(title_be, 'Містар Каралева'), overview_be = COALESCE(overview_be, 'Сучасны шэф-кухар раптам аказваецца ў целе каралевы эпохі Часон, і гэта выклікае хаос для ўсіх навокал.') WHERE media_type = 'TV' AND tmdb_id = 108261;
UPDATE entry SET title_be = COALESCE(title_be, 'Спецыяльная дастаўка'), overview_be = COALESCE(overview_be, 'Кіроўца нелегальнай службы дастаўкі на шалёнай хуткасці возіць злачынцаў — пакуль на яе руках не застаецца сын уцекача.') WHERE media_type = 'MOVIE' AND tmdb_id = 606403;
UPDATE entry SET title_be = COALESCE(title_be, 'Джын, загадай жаданне'), overview_be = COALESCE(overview_be, 'Праз тысячу гадоў дзівакаваты джын вяртаецца, каб выконваць жаданні жанчыны, якая нарадзілася без пачуццяў. Ці здолее яго магія прынесці ў яе свет каханне і цуд?') WHERE media_type = 'TV' AND tmdb_id = 228689;
UPDATE entry SET title_be = COALESCE(title_be, 'Слабы герой'), overview_be = COALESCE(overview_be, 'З дапамогай нечаканых сяброў здольны, але замкнёны вучань супрацьстаіць хуліганам і жорсткім ворагам — не здагадваючыся, наколькі небяспечным стане яго свет.') WHERE media_type = 'TV' AND tmdb_id = 200709;
UPDATE entry SET title_be = COALESCE(title_be, 'Дужая дзяўчына Пон Сун'), overview_be = COALESCE(overview_be, 'Пон Сун, якая ад нараджэння мае звышнатуральную сілу, змагаецца са злом і дабіваецца справядлівасці — а заадно трапляе ў любоўны трохкутнік са сваім начальнікам, дырэктарам кампаніі, і паліцэйскім, у якога закаханая.') WHERE media_type = 'TV' AND tmdb_id = 68814;
UPDATE entry SET title_be = COALESCE(title_be, 'Ахоўнік: самотны і вялікі бог'), overview_be = COALESCE(overview_be, 'У пошуках нявесты, якая здыме з яго праклён неўміручасці, 939-гадовы ахоўнік душ сустракае жняца смерці і жвавую школьніцу з трагічным мінулым.') WHERE media_type = 'TV' AND tmdb_id = 67915;
UPDATE entry SET title_be = COALESCE(title_be, 'Гангстар, паліцэйскі, д''ябал'), overview_be = COALESCE(overview_be, 'Ледзь выжыўшы пасля жорсткага нападу садыста — серыйнага забойцы, крымінальны бос Чан Дон Су застаецца прыніжаным. Поўны рашучасці злавіць забойцу, вядомага як К, ён заключае хісткі саюз з Чон Тхэ Сокам — упартым і непадкупным дэтэктывам, які часта перашкаджае яго незаконнаму бізнесу. Аднак Чан Дон Су хоча смерці К, а Чон Тхэ Сок цвёрда намераны аддаць яго пад суд. Яны дамаўляюцца: хто першы знойдзе К, той і вырашыць яго лёс, — і пачынаецца паляванне, у якім сціраецца мяжа паміж злачынствам і законам.') WHERE media_type = 'MOVIE' AND tmdb_id = 581528;
UPDATE entry SET title_be = COALESCE(title_be, 'Каханне па суседстве'), overview_be = COALESCE(overview_be, 'Жанчына, якая спрабуе пачаць жыццё нанава, вяртаецца ў Карэю, і лёс зноў зводзіць яе з сябрам дзяцінства, з якім яе звязвае няпростая гісторыя.') WHERE media_type = 'TV' AND tmdb_id = 241454;
UPDATE entry SET title_be = COALESCE(title_be, 'Маё імя'), overview_be = COALESCE(overview_be, 'Пасля забойства бацькі апантаная помстай жанчына давяраецца магутнаму крымінальнаму босу — і па яго ўказанні ідзе служыць у паліцыю.') WHERE media_type = 'TV' AND tmdb_id = 110356;
UPDATE entry SET title_be = COALESCE(title_be, 'Сардэчна запрашаем у Самдал-ры'), overview_be = COALESCE(overview_be, 'Страціўшы ранейшую славу, фатографка вяртаецца ў родны гарадок і сустракае сябра дзяцінства — і няскончаны раман успыхвае зноў.') WHERE media_type = 'TV' AND tmdb_id = 219651;
UPDATE entry SET title_be = COALESCE(title_be, 'Нашчадкі сонца'), overview_be = COALESCE(overview_be, 'Пасля выпадковай сустрэчы ў бальніцы палкі вайсковец закахваецца ў таленавітую хірургіню. Розныя погляды на жыццё разводзяць іх, але ў лёсу іншыя планы.') WHERE media_type = 'TV' AND tmdb_id = 65143;
UPDATE entry SET title_be = COALESCE(title_be, 'Паразіты'), overview_be = COALESCE(overview_be, 'Беспрацоўная сям''я Кі Тхэка праяўляе асаблівую цікавасць да багатай і шыкоўнай сям''і Пак, за кошт якой збіраецца жыць, — пакуль не аказваецца ўцягнутай у нечаканае здарэнне.') WHERE media_type = 'MOVIE' AND tmdb_id = 496243;
UPDATE entry SET title_be = COALESCE(title_be, 'Чароўна шалёная'), overview_be = COALESCE(overview_be, 'Вучаніца кандытара жыве і не ведае, што кожную ноч ператвараецца ў дзікую д''ябліцу. Яе сям''я наймае суседа наглядаць за яе начной іпастассю, а ён закахваецца ў яе дзённую і шукае спосаб зняць праклён.') WHERE media_type = 'MOVIE' AND tmdb_id = 873797;
UPDATE entry SET title_be = COALESCE(title_be, 'Нават калі гэтае каханне знікне сёння ўначы'), overview_be = COALESCE(overview_be, 'Старшакласніца кожны дзень прачынаецца, нічога не памятаючы пра ўчорашні. Калі яна згаджаецца сустракацца з сарамлівым аднакласнікам, ці зможа іх каханне расці з кожным новым пачаткам?') WHERE media_type = 'MOVIE' AND tmdb_id = 1466115;
UPDATE entry SET title_be = COALESCE(title_be, 'Ідэальная карона'), overview_be = COALESCE(overview_be, 'У Карэі XXI стагоддзя, дзе дзейнічае канстытуцыйная манархія, спадчынніца чэболя, у якой ёсць усё, акрамя статусу, спрабуе ўзяць будучыню ў свае рукі пасля сустрэчы з самотным прынцам, у якога няма нічога, акрамя тытула. Звязаныя шлюбам па кантракце, яны пачынаюць раман насуперак саслоўным межам, каб перапісаць лёс.') WHERE media_type = 'TV' AND tmdb_id = 278573;
UPDATE entry SET title_be = COALESCE(title_be, 'Ці можна перакласці гэтае каханне?'), overview_be = COALESCE(overview_be, 'Пачуцці знакамітасці і яе перакладчыка губляюцца пры перакладзе, пакуль яны падарожнічаюць па свеце на здымках тэлешоу. Ці знойдзе каханне ўласную мову?') WHERE media_type = 'TV' AND tmdb_id = 229891;
UPDATE entry SET title_be = COALESCE(title_be, 'Кароль зямлі'), overview_be = COALESCE(overview_be, 'У разгар напружанай барацьбы за спадчыну абаяльны спадчыннік сутыкаецца са сваёй працавітай супрацоўніцай, вядомай неадольнай усмешкай, — якую ён трываць не можа.') WHERE media_type = 'TV' AND tmdb_id = 198004;
UPDATE entry SET title_be = COALESCE(title_be, 'Дваццаць пяць, дваццаць адзін'), overview_be = COALESCE(overview_be, 'У часы, калі мары здаюцца недасяжнымі, юная фехтавальшчыца ідзе да вялікіх мэт і сустракае працавітага маладога чалавека, які спрабуе нанава выбудаваць сваё жыццё.') WHERE media_type = 'TV' AND tmdb_id = 129888;
UPDATE entry SET title_be = COALESCE(title_be, 'Правучу цябе'), overview_be = COALESCE(overview_be, 'Гісторыя інспектара Бюро па абароне правоў у сферы адукацыі, якому дзяржава дазволіла ўжываць фізічную сілу і нестандартныя метады, каб прывучаць да дысцыпліны вучняў-хуліганаў і рэфармаваць сістэму адукацыі.') WHERE media_type = 'TV' AND tmdb_id = 276161;
UPDATE entry SET title_be = COALESCE(title_be, 'Агент Кім вяртаецца ў строй'), overview_be = COALESCE(overview_be, 'Калі ў сціплага бацькі знікае дачка, ён успамінае свае старыя навыкі спецаперацый, каб знайсці яе, — і прыцягвае зусім не тую ўвагу.') WHERE media_type = 'TV' AND tmdb_id = 296206;
UPDATE entry SET title_be = COALESCE(title_be, 'Ду На!'), overview_be = COALESCE(overview_be, 'Студэнт спраўляецца з жыццём і вучобай у незвычайных абставінах — ён жыве пад адным дахам з прыгожай былой зоркай K-pop.') WHERE media_type = 'TV' AND tmdb_id = 194797;
UPDATE entry SET title_be = COALESCE(title_be, 'Флекс X Коп'), overview_be = COALESCE(overview_be, 'Паліцэйскі з сям''і чэболя аб''ядноўваецца з загартаваным дэтэктывам, каб лавіць злачынцаў — з дапамогай багацця і немалой долі дасціпнасці.') WHERE media_type = 'TV' AND tmdb_id = 220074;
UPDATE entry SET title_be = COALESCE(title_be, 'Сапраўдная кілерка'), overview_be = COALESCE(overview_be, 'Звычайная на выгляд працуючая маці таемна жыве жыццём легендарнага снайпера, які вяршыць справядлівасць там, дзе закон бяссільны. Вярнуўшыся пасля трохгадовага перапынку, яна мусіць адначасова абараняць сям''ю і знішчаць небяспечных злачынцаў — а тым часам упарты журналіст і няўмольны дэтэктыў падбіраюцца да яе таямніцы.') WHERE media_type = 'TV' AND tmdb_id = 294095;
UPDATE entry SET title_be = COALESCE(title_be, 'Доктар на мяжы'), overview_be = COALESCE(overview_be, 'У Паўднёвай Карэі вайсковая служба абавязковая для ўсіх мужчын. Але нямногія абраныя — напрыклад, прывілеяваныя студэнты-медыкі — могуць замест яе служыць дзяржаўнымі ўрачамі. Гэта гісторыя пра такіх абраных. Пластычнага хірурга То Джы Ыя накіроўваюць на Пхёндандо — адрэзаны ад свету востраў, куды ніхто не хоча ехаць. З першага ж дня пачынаюць з''яўляцца злавесныя знакі. Ці здолее ён вытрымаць цэлы год на гэтым пякельным востраве і выбрацца жывым — ці востраў зламае яго раней?') WHERE media_type = 'TV' AND tmdb_id = 287009;
UPDATE entry SET title_be = COALESCE(title_be, 'Быць не ў парадку — гэта нармальна'), overview_be = COALESCE(overview_be, 'Супрацоўнік псіхіятрычнага аддзялення, які адчайна хоча пазбавіцца душэўнага цяжару і вялікай адказнасці, што ляжала на ім усё жыццё, пачынае ацаляцца дзякуючы нечаканай сустрэчы — з жанчынай, якая піша казкі, але сама ў іх не верыць.') WHERE media_type = 'TV' AND tmdb_id = 96462;
UPDATE entry SET title_be = COALESCE(title_be, 'Містар Нявеста'), overview_be = COALESCE(overview_be, 'Аматар ідэальнай чысціні даведваецца, што яго калега-перфекцыяністка дома — сапраўдная неахайніца. Ці прывядзе гэты «брудны» сакрэт да рамана, калі ён пераедзе да яе, каб навесці парадак?') WHERE media_type = 'TV' AND tmdb_id = 222373;
UPDATE entry SET title_be = COALESCE(title_be, 'Пакуль я не разбурыла другую сям''ю мужа'), overview_be = COALESCE(overview_be, 'Кісарагі Мінары выйшла замуж за Юдая — сваё чыстае каханне са студэнцкіх гадоў, нарадзіла дзяцей і лічыла сваю сям''ю шчаслівай. Гісторыя пачынаецца, калі яна даведваецца, што муж здраджваў ёй 15 гадоў. Мінары клянецца адпомсціць Юдаю, у якога ёсць другая сям''я, і яго каханцы Рыка Міякэ — і для сваёй помсты выкарыстоўвае Ватару, сына Рыка.') WHERE media_type = 'TV' AND tmdb_id = 256380;
UPDATE entry SET title_be = COALESCE(title_be, 'Усё бліжэй'), overview_be = COALESCE(overview_be, '17-гадоваму Акіта засталося жыць усяго год. Ён знаходзіць новы сэнс жыцця ў тым, каб дарыць радасць невылечна хворай дзяўчыне, якой засталося толькі паўгода.') WHERE media_type = 'MOVIE' AND tmdb_id = 1291559;
UPDATE entry SET title_be = COALESCE(title_be, 'Сёгун'), overview_be = COALESCE(overview_be, 'Японія, 1600 год, пярэдадзень грамадзянскай вайны, што вызначыць цэлае стагоддзе. Князь Ёсіі Таранага змагаецца за жыццё, калі яго ворагі ў Савеце рэгентаў аб''ядноўваюцца супраць яго, — і ў гэты час у суседняй рыбацкай вёсцы знаходзяць таямнічы еўрапейскі карабель, выкінуты на бераг.') WHERE media_type = 'TV' AND tmdb_id = 126308;
UPDATE entry SET title_be = COALESCE(title_be, 'Захопленая бальніца'), overview_be = COALESCE(overview_be, 'Дзеянне адбываецца ў вялікай бальніцы, у якую пранікае і якую захоплівае ўзброеная група ў масках д''яблаў. Паліцэйскі Мусасі Сабура, які знаходзіцца ў адпачынку, павінен выратаваць закладнікаў за адведзены час.') WHERE media_type = 'TV' AND tmdb_id = 214952;
UPDATE entry SET title_be = COALESCE(title_be, 'Сінобі: сэрца пад клінком'), overview_be = COALESCE(overview_be, 'Гэнноскэ і Обора паходзяць з варожых вёсак ніндзя, але таемна кахаюць адно аднаго. На штогадовай сустрэчы з князем абвяшчаюць, што паміж пяццю найлепшымі сінобі кожнай вёскі адбудзецца спаборніцтва — бой не на жыццё, а на смерць. Каханне Гэнноскэ і Обора робіцца яшчэ больш немагчымым, калі кожнага з іх выбіраюць узначаліць пяцёрку сваёй вёскі.') WHERE media_type = 'MOVIE' AND tmdb_id = 10116;
UPDATE entry SET title_be = COALESCE(title_be, 'Вазьмі мяне за руку на змярканні'), overview_be = COALESCE(overview_be, 'Асагі Сарамамэ, якая ўсё жыццё пражыла ў глухой японскай вёсцы, наважваецца на смелы крок — едзе ў Токіа ўслед за сябрам дзяцінства і жаніхом. Але жыццё ў вялікім горадзе хутка аказваецца зусім не такім, як яна ўяўляла. Пакуль Асагі шукае сваё месца ў гэтым вялікім новым свеце, яе жыццё робіць цікавы паварот — яна сустракае пачаткоўца-музыку Ота Уміна.') WHERE media_type = 'TV' AND tmdb_id = 217325;
UPDATE entry SET title_be = COALESCE(title_be, 'Мы склалі прыгожы букет'), overview_be = COALESCE(overview_be, 'Двое знаёмяцца, спазніўшыся на апошні цягнік дадому, — і так пачынаюцца цудоўныя адносіны даўжынёй у пяць гадоў.') WHERE media_type = 'MOVIE' AND tmdb_id = 695932;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін. Частка I: Вытокі'), overview_be = COALESCE(overview_be, 'У 1868 годзе, пасля заканчэння вайны Бакумацу, былы наёмны забойца Кэнсін Хімура вандруе па Японіі з мячом з перавернутым лязом, каб абараняць слабых, нікога не забіваючы.') WHERE media_type = 'MOVIE' AND tmdb_id = 127533;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін. Частка II: Вялікі пажар у Кіёта'), overview_be = COALESCE(overview_be, 'Кэнсін асвойтаўся ў новым жыцці з Каору і іншымі сябрамі, калі да яго звяртаецца з просьбай урад Мэйдзі. Макота Сісіа, былы наёмны забойца, як і Кэнсін, быў здраджаны, падпалены і кінуты паміраць. Ён выжыў і цяпер у Кіёта разам з сабранымі ваярамі рыхтуе звяржэнне новага ўрада. Насуперак жаданню Каору Кэнсін неахвотна згаджаецца паехаць у Кіёта і дапамагчы ўтрымаць краіну ад новай грамадзянскай вайны.') WHERE media_type = 'MOVIE' AND tmdb_id = 221731;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін. Частка III: Канец легенды'), overview_be = COALESCE(overview_be, 'Сісіа выходзіць у мора на сваім браняносцы, каб зрынуць урад. Каб спыніць яго, Кэнсін трэніруецца са сваім старым настаўнікам і асвойвае яго апошні прыём.') WHERE media_type = 'MOVIE' AND tmdb_id = 221732;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін: Фінал'), overview_be = COALESCE(overview_be, 'У 1879 годзе Кэнсін і яго саюзнікі сутыкаюцца з наймацнейшым ворагам — яго былым шваграм Энісі Юкісіра і яго паплечнікамі, якія пакляліся адпомсціць.') WHERE media_type = 'MOVIE' AND tmdb_id = 602063;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін: Пачатак'), overview_be = COALESCE(overview_be, 'Перш чым стаць абаронцам, Кэнсін быў страшным наёмным забойцам, вядомым як Батосай. Але сустрэча з пяшчотнай Тамаэ Юкісіра — прыгожай маладой жанчынай, якая носіць у сэрцы вялікі цяжар, — назаўсёды зменіць яго жыццё.') WHERE media_type = 'MOVIE' AND tmdb_id = 672322;
UPDATE entry SET title_be = COALESCE(title_be, 'Каралеўская бітва'), overview_be = COALESCE(overview_be, 'У будучыні японскі ўрад захоплівае клас дзевяцікласнікаў і прымушае іх забіваць адно аднаго паводле рэвалюцыйнага закона «Каралеўская бітва».') WHERE media_type = 'MOVIE' AND tmdb_id = 3176;
UPDATE entry SET title_be = COALESCE(title_be, 'Бліч'), overview_be = COALESCE(overview_be, 'Старшакласнік Іціга Курасакі жыве звычайным жыццём — калі не лічыць таго, што ён бачыць прывідаў і цьмяна памятае смерць маці пры дзіўных абставінах, калі быў дзіцём. Яго спакойны свет раптам рушыцца, калі ён сустракае Рукію Куцікі — багіню смерці.') WHERE media_type = 'MOVIE' AND tmdb_id = 420426;
UPDATE entry SET title_be = COALESCE(title_be, 'Кроў: апошні вампір'), overview_be = COALESCE(overview_be, 'Знешне Сая — прыгожая 16-гадовая дзяўчына, але за гэтай юнай знешнасцю хаваецца змучаная душа 400-гадовай паўкроўкі. Народжаная ад бацькі-чалавека і маці-вампіркі, яна стагоддзямі жыве самотніцай, апантанай адным: з дапамогай самурайскіх навыкаў пазбавіць свет ад вампіраў — увесь час ведаючы, што і сама, як тыя, на каго яна палюе, можа жыць толькі кроўю.') WHERE media_type = 'MOVIE' AND tmdb_id = 1450;
UPDATE entry SET title_be = COALESCE(title_be, 'Выйдзі замуж за майго мужа: Японія'), overview_be = COALESCE(overview_be, 'Міса ўсё жыццё была другарадным персанажам і слепа давярала найлепшай сяброўцы і мужу. Калі яна даведваецца пра іх раман, здрада заканчваецца яе смерцю. Прачнуўшыся на дзесяць гадоў раней, Міса клянецца стаць галоўнай гераіняй уласнай гісторыі. Яна збіраецца знішчыць здраднікаў, ажаніўшы іх адно з адным, але пасля знаёмства са сваім начальнікам пачынае задумвацца, кім яна ёсць насамрэч.') WHERE media_type = 'TV' AND tmdb_id = 290160;
UPDATE entry SET title_be = COALESCE(title_be, 'Зласлівы Аосіма-кун'), overview_be = COALESCE(overview_be, E'Аосіма і Юкіна працуюць у адной кампаніі, але ніколі не размаўлялі. Аднойчы яны выпадкова сустракаюцца ў бары, куды часта ходзіць Юкіна, і аказваюцца побач! Калі ёй тэлефануе сяброўка, Юкіна ўспамінае, што абяцала прыйсці на вяселле «са сваім хлопцам», і панікуе: «О не, мы ж рассталіся паўгода таму!..»\n\nВяселле ўжо на наступным тыдні, і Юкіна не ведае, што рабіць. Яна просіць Аосіму ўсяго на адзін дзень прыкінуцца яе хлопцам і пайсці з ёй на вяселле сяброўкі. На яе здзіўленне, ён згаджаецца! Юкіна ўздыхае з палёгкай, але насамрэч у Аосімы ёсць план…\n\nПакуль яны ўдаюць пару, Аосіма чамусьці пачынае цікавіцца Юкінай, да якой раней быў зусім абыякавы, а Юкіна аказваецца ва ўладзе зласлівага малодшага хлопца-цундэрэ. Чым скончыцца іх «каханне па кантракце»?') WHERE media_type = 'TV' AND tmdb_id = 256381;
UPDATE entry SET title_be = COALESCE(title_be, 'Вірусны хіт'), overview_be = COALESCE(overview_be, 'Старшакласнік, з якога здзекуюцца, за адну ноч становіцца сенсацыяй дзякуючы віруснаму відэа. Але калі нечаканая слава паварочваецца цёмным бокам, яму даводзіцца вучыцца змагацца за сябе.') WHERE media_type = 'TV' AND tmdb_id = 312493;
UPDATE entry SET title_be = COALESCE(title_be, 'Ананімныя рамантыкі'), overview_be = COALESCE(overview_be, 'Геніяльная шакалацье, якая баіцца глядзець людзям у вочы, сустракае спадчынніка, які не можа дакранацца да іншых, — але чамусьці адно на аднаго іх страхі не дзейнічаюць.') WHERE media_type = 'TV' AND tmdb_id = 249054;
UPDATE entry SET title_be = COALESCE(title_be, 'Мой хлопец у аранжавым'), overview_be = COALESCE(overview_be, 'Старшакласніца Моэ пераехала ў новы горад пасля смерці бацькі. Ёй і без таго цяжка ўліцца ў новы клас, таму яна гатова скрозь зямлю праваліцца, калі на вучэбнай пажарнай трывозе яе «ратуе» мясцовы пажарны Кёсукэ… на вачах ва ўсёй школы. Але няёмкі выпадак можа аказацца шчаслівым: суровы, але добры Кёсукэ надае Моэ смеласці выйсці з зоны камфорту і пакінуць у мінулым дні самоты. Не кажучы ўжо пра тое, што неўзабаве яна закахваецца ў яго па вушы!..') WHERE media_type = 'MOVIE' AND tmdb_id = 996499;
UPDATE entry SET title_be = COALESCE(title_be, 'Клічце мяне Ціхіра'), overview_be = COALESCE(overview_be, 'Былая сэкс-работніца, якая ні за што не просіць прабачэння, пачынае працаваць у ларку з бэнта ў маленькім прыморскім гарадку і дорыць суцяшэнне самотным душам, што сустракаюцца на яе шляху.') WHERE media_type = 'MOVIE' AND tmdb_id = 1024621;
UPDATE entry SET title_be = COALESCE(title_be, 'Пяшчотнае веласіпеднае каханне'), overview_be = COALESCE(overview_be, 'Гісторыя кахання паміж Такахасі Рёхэем — клапатлівым маладым хлопцам хуліганскага выгляду, які трымае веламайстэрню, — і Хано Тамака, сарамлівай 30-гадовай офіснай работніцай.') WHERE media_type = 'TV' AND tmdb_id = 209843;
UPDATE entry SET title_be = COALESCE(title_be, 'Гэты геній прывязаўся да сваёй фальшывай дзяўчыны'), overview_be = COALESCE(overview_be, E'Хосіна Рын, «добрая, але няшчасная дзяўчына, якая клапоціцца пра іншых», напярэдадні 30-годдзя апынулася на самым дне: ні працы, ні хлопца.\n\nПа рэкамендацыі старэйшага брата яна пачынае працаваць хатняй памочніцай у Вакацукі Іку, геніяльнага праграміста. Аднак яе наймальнік — той самы «загадкава нячулы мужчына», які калісьці разбурыў яе планы на шлюб. Іх адносіны пачынаюцца з найгоршай з магчымых сустрэч, але з часам у дамову пра хатнюю працу трапляе і «кантракт рамантычнага партнёра»…\n\nПачынаецца гісторыя пяшчотнага кахання з моцным пачуццём уласніцтва, якую вядзе няўклюдны «геній»!') WHERE media_type = 'TV' AND tmdb_id = 317415;
UPDATE entry SET title_be = COALESCE(title_be, 'Дата вяселля'), overview_be = COALESCE(overview_be, '«Замуж у 26», «першае дзіця ў 27», «другое — у 29»… Яна заўсёды проста лічыла, што ўсё так і будзе… 28-гадовая Каваі Ёсіка дагэтуль не замужам. За некалькі дзён да 29-годдзя ёй разбіваюць сэрца. Па дарозе дадому яна сустракае калегу, Юкі-сана, і не можа ўтрымацца, каб не расказаць яму пра тое, што толькі што здарылася. І раптам Юкі-сан прапануе Ёсіка ажаніцца з ім праз год — але толькі калі…') WHERE media_type = 'TV' AND tmdb_id = 230214;
UPDATE entry SET title_be = COALESCE(title_be, 'Фальшывы шлюб'), overview_be = COALESCE(overview_be, 'Яэ — непрыкметная дзяўчына, якая працуе ў кавярні і жыве разам з сяброўкай. Калі сяброўка раптам выходзіць замуж, Яэ не можа плаціць за жыллё, а ў той жа дзень яшчэ і губляе працу! І толькі калі яе кідае хлопец, яна канчаткова апускаецца на самае дно.') WHERE media_type = 'TV' AND tmdb_id = 228919;
UPDATE entry SET title_be = COALESCE(title_be, 'Наперад'), overview_be = COALESCE(overview_be, 'Трое школьнікаў становяцца блізкімі, як родныя. Але ці ўмацуе цяжар дарослага жыцця іх адносіны — або разбурыць іх?') WHERE media_type = 'TV' AND tmdb_id = 107329;
UPDATE entry SET title_be = COALESCE(title_be, 'Эксклюзіўная казка'), overview_be = COALESCE(overview_be, 'Лін Чао і Сяо Ту яшчэ з дзіцячага садка — супернікі і неразлучныя сябры. Нягледзячы на свой бліскучы розум і перфекцыянізм, Лін Чао ў вачах уласнай маці заўсёды заставаўся ў цені Сяо Ту. Яны растуць разам, і іх жартаўлівае суперніцтва ператвараецца ў нешта большае.') WHERE media_type = 'TV' AND tmdb_id = 231306;
UPDATE entry SET title_be = COALESCE(title_be, 'Аватар караля'), overview_be = COALESCE(overview_be, 'Калі элітнага геймера выціскаюць з прафесійнай каманды, ён становіцца адміністратарам інтэрнэт-кафэ і пачынае ўсё нанава, каб вярнуць сабе славу ў анлайне.') WHERE media_type = 'TV' AND tmdb_id = 91470;
UPDATE entry SET title_be = COALESCE(title_be, 'Таемнае каханне'), overview_be = COALESCE(overview_be, 'Сан Чжы са школьных гадоў закаханая ў Дуань Цзясюя. Калі лёс зноў зводзіць іх разам, у іх з''яўляецца шанец на пяшчотныя адносіны.') WHERE media_type = 'TV' AND tmdb_id = 210733;
UPDATE entry SET title_be = COALESCE(title_be, 'Хачу з''есці тваю падстраўнікавую залозу'), overview_be = COALESCE(overview_be, 'Калі ў аднакласніцы, у якую ён закаханы, выяўляюць хваробу падстраўнікавай залозы, звычайны старшакласнік вырашае зрабіць яе апошнія дні як мага больш яркімі.') WHERE media_type = 'MOVIE' AND tmdb_id = 504253;
UPDATE entry SET title_be = COALESCE(title_be, 'Сталёвы алхімік'), overview_be = COALESCE(overview_be, 'Двух юных братоў выхоўваюць як алхімікаў, але, спрабуючы здзейсніць забаронены абрад, яны атрымліваюць цяжкія калецтвы і пачынаюць шукаць адзінае, што можа іх выратаваць, — легендарны філасофскі камень.') WHERE media_type = 'TV' AND tmdb_id = 37863;
UPDATE entry SET title_be = COALESCE(title_be, 'Клінок, які знішчае дэманаў'), overview_be = COALESCE(overview_be, 'Пасля нападу дэмана яго сям''я загінула, а сястра аказалася праклятай. Тандзіра выпраўляецца ў небяспечнае падарожжа, каб знайсці лекі і адпомсціць за тых, каго страціў.') WHERE media_type = 'TV' AND tmdb_id = 85937;
UPDATE entry SET title_be = COALESCE(title_be, 'Майстры мяча анлайн'), overview_be = COALESCE(overview_be, 'У недалёкай будучыні выходзіць шматкарыстальніцкая ролевая анлайн-гульня ў віртуальнай рэальнасці (VRMMORPG) пад назвай Sword Art Online, дзе гульцы кіруюць сваімі аватарамі ўласным целам з дапамогай прылады Nerve Gear. Аднойчы гульцы выяўляюць, што не могуць выйсці з гульні: яе стваральнік трымае іх у палоне, пакуль яны не дабяруцца да 100-га паверха вежы і не перамогуць фінальнага боса. Аднак смерць у гульні азначае смерць у рэальным жыцці. Іх барацьба за выжыванне пачынаецца…') WHERE media_type = 'TV' AND tmdb_id = 45782;
UPDATE entry SET title_be = COALESCE(title_be, 'Магічная бітва'), overview_be = COALESCE(overview_be, 'Юдзі Ітадоры — хлопец з неверагоднай фізічнай сілай, які, аднак, жыве зусім звычайным жыццём старшакласніка. Аднойчы, каб выратаваць аднакласніка, на якога напалі праклёны, ён з''ядае палец Рёмэна Сукуны і прымае праклён ва ўласную душу. З таго часу ён дзеліць адно цела з Рёмэнам Сукунай. Пад кіраўніцтвам наймацнейшага з чараўнікоў, Сатору Годзё, Ітадоры паступае ў Такійскую магічную школу — арганізацыю, якая змагаецца з праклёнамі… і так пачынаецца гераічная гісторыя хлопца, які сам стаў праклёнам, каб выганяць праклёны, — жыццё, з якога ўжо няма шляху назад.') WHERE media_type = 'TV' AND tmdb_id = 95479;
UPDATE entry SET title_be = COALESCE(title_be, 'Магічная бітва 0'), overview_be = COALESCE(overview_be, 'Юта Окоцу — нервовы старшакласнік з сур''ёзнай праблемай: яго сяброўка дзяцінства Рыка ператварылася ў праклён і не пакідае яго ў спакоі. Рыка — не звычайны праклён, таму яго бяду заўважае Сатору Годзё, настаўнік Магічнай школы, дзе пачаткоўцы-экзарцысты вучацца змагацца з праклёнамі. Годзё ўгаворвае Юту паступіць, але ці паспее ён навучыцца дастаткова, каб супрацьстаяць праклёну, які яго пераследуе?') WHERE media_type = 'MOVIE' AND tmdb_id = 810693;
UPDATE entry SET title_be = COALESCE(title_be, 'Бяздомны бог'), overview_be = COALESCE(overview_be, 'Ята пакуль усяго толькі дробны бог, але ён поўны рашучасці дабіцца вялікай славы, і ў яго ёсць план. На жаль, усё ідзе зусім не так, як ён хацеў бы. У яго няма ніводнага прысвечанага яму свяцілішча, напарніца толькі што сышла, і цяпер трэба шукаць новую боскую зброю. Якраз калі ўсё здаецца змрочным, ён сустракае дзяўчыну па імені Хіёры — і назаўсёды мяняе яе жыццё.') WHERE media_type = 'TV' AND tmdb_id = 64710;
UPDATE entry SET title_be = COALESCE(title_be, 'Забойца Акамэ!'), overview_be = COALESCE(overview_be, 'Юны Тацумі накіроўваецца ў сталіцу Імперыі, каб зарабіць грошай для сваіх галодных землякоў, і сутыкаецца са светам неймавернай распусты, дзе пануе бязлітасны прэм''ер-міністр, які кіруе імператарам-дзіцём. Тацумі вярбуе «Начны рэйд» — група наёмных забойцаў, якая змагаецца з карупцыяй, бязлітасна знішчаючы чыноўнікаў і прывілеяваных дваран.') WHERE media_type = 'TV' AND tmdb_id = 61223;
UPDATE entry SET title_be = COALESCE(title_be, 'Бліч'), overview_be = COALESCE(overview_be, 'Колькі сябе памятае, Іціга Курасакі бачыць прывідаў. Але сустрэча з Рукіяй — жніцай душ, якая змагаецца са злымі духамі, вядомымі як Пустыя, — назаўсёды мяняе яго жыццё. Цяпер, атрымаўшы вялізны запас духоўнай энергіі, Іціга адкрывае сваё сапраўднае прызначэнне: абараняць жывых і мёртвых ад зла.') WHERE media_type = 'TV' AND tmdb_id = 30984;
UPDATE entry SET title_be = COALESCE(title_be, 'Каўбой Бібоп'), overview_be = COALESCE(overview_be, '2071 год. Прыкладна праз пяцьдзясят гадоў пасля аварыі з гіперпрасторавай брамай, якая зрабіла Зямлю амаль непрыдатнай для жыцця, чалавецтва каланізавала большасць камяністых планет і спадарожнікаў Сонечнай сістэмы. На фоне росту злачыннасці Міжпланетная паліцыя Сонечнай сістэмы (ISSP) увяла легальную сістэму кантрактаў: зарэгістраваныя паляўнічыя за галовамі, якіх таксама называюць «каўбоямі», ловяць злачынцаў і дастаўляюць іх жывымі за ўзнагароду.') WHERE media_type = 'TV' AND tmdb_id = 30991;
UPDATE entry SET title_be = COALESCE(title_be, 'Каўбой Бібоп: Фільм'), overview_be = COALESCE(overview_be, 'На двары 2071 год. Пасля тэракта на насельніцтва Марса выпушчаны смяротны вірус, і ўрад прызначыў найбуйнейшую ў гісторыі ўзнагароду за злоўленне таго, хто за гэтым стаіць. Экіпаж паляўнічых за галовамі з касмічнага карабля «Бібоп» — Спайк, Фэй, Джэт і Эд — бярэцца за справу ў надзеі атрымаць узнагароду. Аднак таямніца вакол Вінсента, чалавека, які за ўсё адказны, глыбейшая, чым яны маглі ўявіць, — і палююць на яго не толькі яны.') WHERE media_type = 'MOVIE' AND tmdb_id = 11299;
UPDATE entry SET title_be = COALESCE(title_be, 'Паразіт: вучэнне аб жыцці'), overview_be = COALESCE(overview_be, 'На Зямлю трапляе від іншапланетных паразітаў, якія хутка пранікаюць у чалавецтва, усяляючыся ў мозг уразлівых ахвяр. Гэта ненасытныя істоты, якія атрымліваюць поўны кантроль над носьбітам і здольныя змяняць сваю форму, каб паляваць на людзей, якія нічога не падазраюць. Старшакласнік Сін''іці Ідзумі становіцца ахвярай аднаго з такіх паразітаў, але істоце не ўдаецца захапіць яго мозг, і яна аказваецца ў яго правай руцэ.') WHERE media_type = 'TV' AND tmdb_id = 61459;
UPDATE entry SET title_be = COALESCE(title_be, 'Чалавек-бензапіла'), overview_be = COALESCE(overview_be, 'У Дэндзі простая мара — жыць шчасліва і спакойна, бавячы час з дзяўчынай, якая яму падабаецца. Аднак да гэтага далёка: якудза прымушае Дэндзі забіваць дэманаў, каб расплаціцца з непамернымі даўгамі. Выкарыстоўваючы свайго хатняга дэмана Поціту як зброю, ён гатовы на ўсё дзеля невялікіх грошай.') WHERE media_type = 'TV' AND tmdb_id = 114410;
UPDATE entry SET title_be = COALESCE(title_be, 'Сям''я шпіёна'), overview_be = COALESCE(overview_be, 'Шпіён, наёмная забойца і тэлепатка аб''ядноўваюцца, каб удаваць сям''ю, — у кожнага на гэта свае прычыны, і кожны хавае ад астатніх сваю сапраўдную асобу.') WHERE media_type = 'TV' AND tmdb_id = 120089;
UPDATE entry SET title_be = COALESCE(title_be, 'Сям''я шпіёна. Код: Белы'), overview_be = COALESCE(overview_be, 'Лойд вязе сям''ю на зімовыя выхадныя, але гэта толькі прыкрыццё: ён спрабуе прасунуцца ў сваім цяперашнім заданні — аперацыі «Стрыкс». Зрабіць гэта аказваецца няпроста, калі Аня памылкова ўмешваецца ў справу і запускае падзеі, якія пагражаюць міру ва ўсім свеце.') WHERE media_type = 'MOVIE' AND tmdb_id = 1062807;
UPDATE entry SET title_be = COALESCE(title_be, 'Пажыральнік душ'), overview_be = COALESCE(overview_be, 'Дзеянне адбываецца ў тэхнічнай школе Сінігамі для майстроў зброі; у цэнтры сюжэта — тры каманды, кожная з якіх складаецца з майстра і чалавека-зброі. Каб зрабіць зброю «Касой смерці» — гэта найвышэйшы тытул для зброі, які робіць яе вартай рук Сінігамі, — яны павінны сабраць душы 99 злых людзей і адной ведзьмы. Мака і Соўл Ітэр, Блэк Стар і Цубакі, а таксама Дэт зэ Кід з Пэці і Ліз Томпсан — галоўныя героі гэтай гісторыі. Акрамя збору душ, гэтыя вучні Сібусэна абараняюць Горад Смерці ад адных з наймагутнейшых істот, не кідаючы пры гэтым вучобу і імкнучыся стаць мацнейшымі.') WHERE media_type = 'TV' AND tmdb_id = 37305;
UPDATE entry SET title_be = COALESCE(title_be, 'Рэінкарнацыя беспрацоўнага'), overview_be = COALESCE(overview_be, '34-гадовага няўдачніка збівае грузавік, але на гэтым яго гісторыя не заканчваецца. Перанарадзіўшыся немаўлём у новым свеце, Рудзі будзе выкарыстоўваць кожную магчымасць, каб пражыць жыццё, пра якое заўсёды марыў. З новымі сябрамі, толькі што набытымі магічнымі здольнасцямі і смеласцю рабіць тое, на што раней не наважваўся, ён выпраўляецца ў эпічную прыгоду — захаваўшы ўвесь свой мінулы досвед!') WHERE media_type = 'TV' AND tmdb_id = 94664;
UPDATE entry SET title_be = COALESCE(title_be, 'Дарора'), overview_be = COALESCE(overview_be, 'У эпоху Ваюючых правінцый малады злодзей Дарора сустракае Хякімару — дзіўнага сляпога юнака, які замест страчаных канечнасцей мае грозныя пратэзы. Часткі цела Хякімару яго бацька аддаў дванаццаці дэманам у абмен на ўладу, але дзякуючы добраму лекару Хякімару перажыў гэтае жахлівае выпрабаванне. Цяпер ён блукае па краіне ў пошуках страчаных частак цела, і разам з Дарора яны будуць змагацца за выжыванне ў бязлітасным свеце, які кішыць дэманамі.') WHERE media_type = 'TV' AND tmdb_id = 83100;
UPDATE entry SET title_be = COALESCE(title_be, 'Самурай Чамплу'), overview_be = COALESCE(overview_be, 'Мугэн — люты ваяр, які ў баі рухаецца нібы ў брэйк-дансе, — вымушаны мець справу з халоднакроўным і фанабэрыстым Дзінам, самураем, які лічыць сябе вышэйшым за ўсіх. Гэтых заклятых ворагаў зводзіць разам Фу — дзеля аднаго асаблівага задання.') WHERE media_type = 'TV' AND tmdb_id = 1063;
UPDATE entry SET title_be = COALESCE(title_be, 'Гэтая фарфоравая лялька закахалася'), overview_be = COALESCE(overview_be, 'Старшакласнік Вакана Годзё хоча стаць касірасі — майстрам, які робіць традыцыйныя японскія лялькі хіна. Ён захоплены сваім рамяством, але нічога не ведае пра апошнія модныя павевы, і яму цяжка ўліцца ў клас. Папулярныя аднакласнікі — асабліва адна дзяўчына, Марын Кітагава, — нібы жывуць у зусім іншым свеце. Усё мяняецца аднойчы, калі яна дзеліцца з ім нечаканым сакрэтам — і іх зусім розныя светы сутыкаюцца.') WHERE media_type = 'TV' AND tmdb_id = 123249;
UPDATE entry SET title_be = COALESCE(title_be, 'За мяжой'), overview_be = COALESCE(overview_be, 'Цёмнае фэнтэзі пра вучня другога года старэйшай школы Акіхіта Камбару. Хлопец выглядае як чалавек, але ён напалову ёму і неўразлівы да ран, бо хутка ацаляецца. Аднойчы Акіхіта сустракае першакласніцу Мірай Курыяму, калі здаецца, што яна вось-вось скочыць з даху школы. Мірай — ізгой з-за здольнасці кіраваць кроўю, што ў свеце духаў лічыцца ерассю. Пасля таго як Акіхіта ратуе Мірай, пачынаюць адбывацца трывожныя падзеі.') WHERE media_type = 'TV' AND tmdb_id = 61695;
UPDATE entry SET title_be = COALESCE(title_be, 'За мяжой: Я буду тут — Будучыня'), overview_be = COALESCE(overview_be, 'Бітва скончана, і цяпер яны могуць жыць звычайным жыццём… прынамсі, так ім здавалася. Не паспелі яны нарадавацца таму, што цудам выратавалі Мірай з-за Мяжы, як аказалася, што Мірай страціла ўсе ўспаміны. Акіхіта, цяпер вучань выпускнога класа, пачынае пазбягаць Мірай, мяркуючы, што так будзе лепш. Не ведаючы пра пачуцці Акіхіта, Мірай спрабуе зблізіцца з ім. Потым перад імі з''яўляецца нехта, хто ведае Мірай. Намаганні Акіхіта аказваюцца марнымі, і Мірай зноў уступае ў бітву, якая прымушае яе зазірнуць у сябе.') WHERE media_type = 'MOVIE' AND tmdb_id = 333622;
UPDATE entry SET title_be = COALESCE(title_be, 'Чорная лагуна'), overview_be = COALESCE(overview_be, 'Гісторыя пра каманду піратаў-наёмнікаў, вядомую як «Кампанія Лагуна», якая ў першай палове і сярэдзіне 1990-х займаецца кантрабандай у морах Паўднёва-Усходняй Азіі. Іх база знаходзіцца ў выдуманым партовым горадзе Раанапур на паўднёвым усходзе Тайланда, непадалёк ад мяжы з Камбоджай.') WHERE media_type = 'TV' AND tmdb_id = 12598;
UPDATE entry SET title_be = COALESCE(title_be, 'Павышэнне ўзроўню ў адзіночку'), overview_be = COALESCE(overview_be, 'Кажуць, усё, што цябе не забівае, робіць цябе мацнейшым, але да самага слабага паляўнічага ў свеце Сон Джын У гэта не датычыцца. Пасля таго як яго жорстка забілі монстры ў падзямеллі высокага рангу, Джын У вярнуўся разам з Сістэмай — праграмай, якую бачыць толькі ён і якая павышае яго ўзровень ва ўсім. Цяпер ён хоча раскрыць таямніцы сваіх сіл і падзямелля, якое іх спарадзіла.') WHERE media_type = 'TV' AND tmdb_id = 127532;
UPDATE entry SET title_be = COALESCE(title_be, 'Дзіця айдала'), overview_be = COALESCE(overview_be, 'Урач з маленькага гарадка трапляе ў бязлітасны свет шоу-бізнесу, калі яго шлях перасякаецца з папулярнай юнай зоркай-айдалам, якая хавае таямніцу.') WHERE media_type = 'TV' AND tmdb_id = 203737;
UPDATE entry SET title_be = COALESCE(title_be, 'Дан Да Дан'), overview_be = COALESCE(overview_be, 'Паспрачаўшыся, хто існуе насамрэч — прывіды ці іншапланецяне, двое старшакласнікаў сутыкаюцца з жахлівымі паранармальнымі пагрозамі, атрымліваюць звышздольнасці і, магчыма, нават закахваюцца?!') WHERE media_type = 'TV' AND tmdb_id = 240411;
UPDATE entry SET title_be = COALESCE(title_be, 'Пякельны рай'), overview_be = COALESCE(overview_be, 'Дзеля шанцу на памілаванне ніндзя — наёмны забойца далучаецца да іншых асуджаных злачынцаў у падарожжы на таямнічы востраў па эліксір неўміручасці.') WHERE media_type = 'TV' AND tmdb_id = 117465;
UPDATE entry SET title_be = COALESCE(title_be, 'Усемагутны ў цені'), overview_be = COALESCE(overview_be, 'Уладары ценяў — гэта тыя, хто застаецца незаўважаным і выдае сябе за непрыкметных людзей, а насамрэч кіруе ўсім з-за куліс. Сід больш за ўсё на свеце хоча стаць менавіта такім, і такая дробязь, як сумная рэальнасць, яму не перашкодзіць! Ён таемна трэніруецца кожную ноч, рыхтуючыся аднойчы ўзняцца да ўлады, — але яго лёс перакрэслівае звычайная (хоць і смяротная) аварыя. Аднак, прачнуўшыся ў іншым свеце, ён раптам аказваецца на чале сапраўднай таемнай арганізацыі, якая змагаецца са злом у цені, — і нарэшце атрымлівае шанец увасобіць усе свае шалёныя фантазіі!') WHERE media_type = 'TV' AND tmdb_id = 119495;
UPDATE entry SET title_be = COALESCE(title_be, 'Трайган'), overview_be = COALESCE(overview_be, 'Дзеянне «Трайгана» адбываецца ў далёкай будучыні на пустыннай планеце. Вэш Ураган — стралок з настолькі страшнай славай, што за яго галаву прызначана ўзнагарода ў 60 000 000 000 падвойных долараў. Цэлыя гарады эвакуіруюцца, ледзь пачуўшы пра яго набліжэнне. Але сапраўдны Вэш Ураган — загадкавы і супярэчлівы галоўны герой — куды больш высакародны, хоць звычайна і паводзіць сябе як поўны ёлупень.') WHERE media_type = 'TV' AND tmdb_id = 26453;
UPDATE entry SET title_be = COALESCE(title_be, 'Хелсінг'), overview_be = COALESCE(overview_be, E'Вампіры існуюць. Абавязак «Хелсінга», арганізацыі, якую фінансуе брытанскі ўрад, — хаваць гэты жахлівы факт і абараняць насельніцтва, якое жыве ў шчаслівым няведанні.\n\nАпошнім часам актыўнасць вампіраў расце, і прычына гэтага больш трывожная, чым хто-небудзь мог уявіць.') WHERE media_type = 'TV' AND tmdb_id = 16830;
UPDATE entry SET title_be = COALESCE(title_be, 'Маналог аптэкаркі'), overview_be = COALESCE(overview_be, 'Маомао жыла спакойным жыццём са сваім бацькам-аптэкарам. Пакуль аднойчы яе не прадалі простай служанкай у імператарскі палац. Але пакорлівае жыццё сярод знаці — не для яе. Таму, калі імператарскія спадчыннікі захворваюць, яна вырашае ўмяшацца і знайсці лекі! Гэта прыцягвае ўвагу Дзінсі, прыгожага палацавага чыноўніка, які павышае яе па службе. Цяпер яна робіць сабе імя, разгадваючы медыцынскія загадкі!') WHERE media_type = 'TV' AND tmdb_id = 220542;
UPDATE entry SET title_be = COALESCE(title_be, 'Берсерк'), overview_be = COALESCE(overview_be, 'Гатс, вандроўны наёмнік, далучаецца да Атрада Ястраба пасля таго, як яго перамог у паядынку Грыфіт — лідар і заснавальнік атрада. Разам яны перамагаюць у кожнай бітве, але ў цені тоіцца нешта злавеснае.') WHERE media_type = 'TV' AND tmdb_id = 35935;
UPDATE entry SET title_be = COALESCE(title_be, 'Покліч ночы'), overview_be = COALESCE(overview_be, 'Новая спадарожніца Ко, Надзуна, магла б адкрыць яму цёмныя дары і вампірскую неўміручасць. Але ёсць умовы, якія Ко мусіць выканаць, перш чым стаць вампірам, і яму давядзецца высветліць, як далёка ён гатовы зайсці, каб задаволіць свае жаданні.') WHERE media_type = 'TV' AND tmdb_id = 138357;
UPDATE entry SET title_be = COALESCE(title_be, 'Кайдзю № 8'), overview_be = COALESCE(overview_be, 'У свеце, які церпіць ад істот, вядомых як кайдзю, Кафка Хібіна марыў паступіць у Сілы абароны. Ён паабяцаў зрабіць гэта разам з сяброўкай дзяцінства Мінай Асіра. Але неўзабаве жыццё разводзіць іх у розныя бакі. Працуючы прыбіральшчыкам пасля бітваў з кайдзю, Кафка знаёміцца з Рэна Іцікавам. Рашучасць Рэна паступіць у Сілы абароны абуджае ў Кафку ранейшае абяцанне — стаць побач з Мінай і абараняць чалавецтва.') WHERE media_type = 'TV' AND tmdb_id = 207468;
UPDATE entry SET title_be = COALESCE(title_be, 'Сталёвая трывога!'), overview_be = COALESCE(overview_be, 'Канамэ Цідоры — адна з самых папулярных дзяўчат у сваёй школе, але, на жаль, турбавацца ёй варта пра сваю папулярнасць па-за школай. Канамэ не ведае, што тэрарысты рыхтуюць яе выкраданне, бо лічаць, што яна валодае рэдкімі і жаданымі здольнасцямі «Нашэптаных». І тут з''яўляецца Сосукэ Сагара — адчайны салдат таемнай антытэрарыстычнай арганізацыі «Міфрыл». Ён пад прыкрыццём паступае ў школу Канамэ, каб яе абараняць. Магчыма, ён і ас у кабіне баявога робата «Арм Слэйв», але ніякая падрыхтоўка ў свеце не магла падрыхтаваць яго да такой зоны баявых дзеянняў, як старэйшая школа.') WHERE media_type = 'TV' AND tmdb_id = 39379;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін'), overview_be = COALESCE(overview_be, 'Эпоха Мэйдзі стала для Японіі часам вялікага абнаўлення: мячы і забойствы апынуліся па-за законам. Аднак многія з тых, хто перажыў часы рэвалюцыі, яшчэ жывыя: яны хаваюцца ў цені і чакаюць выпадку зноў пусціць у ход свае смертаносныя клінкі. Толькі Кэнсін Хімура, калісьці адзін з самых бязлітасных забойцаў, спадзяецца захаваць гонар мечніка і пры гэтым жыць у новай эпосе.') WHERE media_type = 'TV' AND tmdb_id = 28136;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін'), overview_be = COALESCE(overview_be, 'Мінула дзесяць гадоў пасля заканчэння Бакумацу — эпохі вайны, калі грамадзяне паўсталі супраць сёгуната Такугава. Рэвалюцыянеры хацелі стварыць мірны час і квітнеючую краіну, вольную ад прыгнёту. Настала новая эпоха Мэйдзі, але міру ўсё яшчэ няма. Мячы забаронены, аднак людзей па-ранейшаму забіваюць на вуліцах. Сіротам ветэранаў вайны няма куды падзецца, а ўрад, здаецца, заняты толькі тым, каб набіваць уласныя кішэні.') WHERE media_type = 'TV' AND tmdb_id = 210879;
UPDATE entry SET title_be = COALESCE(title_be, 'Самурай Ікс: Фільм'), overview_be = COALESCE(overview_be, 'Вайна супраць сёгуната Такугава скончылася шмат гадоў таму. Але ёсць тыя, хто не задаволены яе вынікам. Сігурэ Такімі бачыў, як яго сяброў і родных секлі мячамі ў імя свабоды і росквіту. Цяпер ён і атрад адчайных паўстанцаў пакляліся звесці апошнія рахункі. На іх шляху стаіць толькі адзін чалавек — бадзяга Кэнсін. Ці возьме былы наёмны забойца ў рукі меч, каб біцца зноў? Калі Сігурэ даведаецца, кім насамрэч ёсць Кэнсін, і яго барацьба ператворыцца ў асабістую помсту, у маладога героя не застанецца выбару.') WHERE media_type = 'MOVIE' AND tmdb_id = 39977;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін: Давер і здрада'), overview_be = COALESCE(overview_be, '«Бадзяга Кэнсін: Давер і здрада» расказвае пра вытокі чалавека, які будзе насіць імя Хітакіры Батосай, — задоўга да таго, як ён пакляўся не забіваць, і да таго, як набыў славу наёмнага забойцы. Сэрца юнака разрываецца паміж справядлівасцю і заганай, а ад яго ўчынкаў залежыць лёс цэлай краіны.') WHERE media_type = 'TV' AND tmdb_id = 317885;
UPDATE entry SET title_be = COALESCE(title_be, 'Бадзяга Кэнсін: Адлюстраванне'), overview_be = COALESCE(overview_be, 'Кэнсін і Каору жанатыя. Кэнсін пакідае Каору з іх сынам Кэндзі, каб узначаліць рэвалюцыю ў Кітаі. Але абое пакутуюць ад хваробы, якая здаецца невылечнай. Праз 15 гадоў Кэнсін спрабуе вярнуцца дадому да жонкі, пакуль яна не памерла ад гора. Пакуль ён з цяжкасцю дабіраецца дадому, перад ім паўстаюць успаміны пра былыя сустрэчы з сябрамі і ворагамі.') WHERE media_type = 'MOVIE' AND tmdb_id = 1502038;
UPDATE entry SET title_be = COALESCE(title_be, 'Дні Сакамота'), overview_be = COALESCE(overview_be, 'Таро Сакамота, калісьці найвялікшы кілер з усіх, пакінуў справу дзеля кахання. Але калі мінулае даганяе яго, ён мусіць змагацца, каб абараніць сваю любімую сям''ю.') WHERE media_type = 'TV' AND tmdb_id = 207332;
UPDATE entry SET title_be = COALESCE(title_be, 'Сшытак смерці'), overview_be = COALESCE(overview_be, 'Лайт Ягамі — выдатнік з бліскучай будучыняй, і яму смяротна сумна. Але ўсё мяняецца, калі ён знаходзіць Сшытак смерці — нататнік, які выпусціў з рук свавольны сінігамі, бог смерці. Любы чалавек, чыё імя запісана ў сшытку, памірае, і Лайт клянецца выкарыстаць сілу Сшытка смерці, каб пазбавіць свет ад зла. Але ці дасягне Лайт сваёй высакароднай мэты — ці Сшытак смерці ператворыць яго ў тое самае, з чым ён змагаецца?') WHERE media_type = 'TV' AND tmdb_id = 13916;
UPDATE entry SET title_be = COALESCE(title_be, 'Прывід у даспехах: Сіндром адзіночкі'), overview_be = COALESCE(overview_be, 'У будучыні, дзе тэхналагічныя паляпшэнні цела і робататэхніка сталі звыклай часткай жыцця, маёр Матока Кусанагі і Дзявяты аддзел бяруцца за справы, занадта складаныя для паліцыі. У Дзявятым аддзеле служаць хакеры, снайперы, дэтэктывы і кібаргі — усе яны імкнуцца сарваць планы кіберзлачынцаў, якія хочуць напасці на нявінных.') WHERE media_type = 'TV' AND tmdb_id = 1095;
UPDATE entry SET title_be = COALESCE(title_be, 'Аватар караля'), overview_be = COALESCE(overview_be, 'У шматкарыстальніцкай анлайн-гульні «Слава» Е Сю лічаць жывым падручнікам і прафесійным гульцом найвышэйшага класа. Аднак па мностве прычын яго выганяюць з каманды. Пакінуўшы прафесійную сцэну, ён уладкоўваецца адміністратарам у інтэрнэт-кафэ. Калі «Слава» запускае дзясяты сервер, ён зноў з галавой акунаецца ў гульню. З дзесяцігадовым досведам, успамінамі пра мінулае і незавершанай самаробнай зброяй ён пачынае свой шлях назад да вяршыні!') WHERE media_type = 'TV' AND tmdb_id = 71194;
UPDATE entry SET title_be = COALESCE(title_be, 'Аватар караля: Дзеля славы'), overview_be = COALESCE(overview_be, 'У гэтым прыквеле анімацыйнага серыяла «Аватар караля» Е Сю ўваходзіць у свет прафесійнай гульні «Слава» і ўдзельнічае ў першым турніры Прафесійнай лігі.') WHERE media_type = 'MOVIE' AND tmdb_id = 613200;
UPDATE entry SET title_be = COALESCE(title_be, 'Я атрымаў чыт-навык у іншым свеце і стаў непераможным і ў рэальным'), overview_be = COALESCE(overview_be, 'Перад хлопцам, з якога ўсё жыццё жорстка здзекаваліся, адчыняюцца дзверы ў іншы свет. Гэтая альтэрнатыўная рэальнасць дае яму доступ да самых розных рэчаў — напрыклад, да чыт-навыкаў і партала, праз які можна падарожнічаць паміж старым і новым светамі! Ці здолее галоўны няўдачнік класа змяніць сваё жыццё дома?..') WHERE media_type = 'TV' AND tmdb_id = 208493;
UPDATE entry SET title_be = COALESCE(title_be, 'Д''ябал можа плакаць'), overview_be = COALESCE(overview_be, 'Прыгоды паляўнічага на дэманаў Дантэ, які сам напалову дэман, напалову чалавек.') WHERE media_type = 'TV' AND tmdb_id = 12577;
UPDATE entry SET title_be = COALESCE(title_be, 'Сіняя скрыня'), overview_be = COALESCE(overview_be, 'Тайкі Інамата любіць бадмінтон, але яму яшчэ далёка да нацыянальнага чэмпіянату. Убачыўшы, як старшакласніца Цінацу Кано з поўнай аддачай трэніруецца ў жаночай баскетбольнай камандзе, Тайкі закахваецца ў яе па вушы. Калі нечаканы паварот падзей збліжае іх, спорт, магчыма, перастане быць першым, пра што яны думаюць!') WHERE media_type = 'TV' AND tmdb_id = 207347;
UPDATE entry SET title_be = COALESCE(title_be, 'Няўдалы прызыў: я стаў наймацнейшым і знішчыў усё нізкаўзроўневымі заклёнамі'), overview_be = COALESCE(overview_be, 'У школе Тока заўсёды быў непрыкметным. І калі яго разам з аднакласнікамі прызываюць у іншы свет, нічога не мяняецца! Усе атрымліваюць навыкі найвышэйшага рангу — акрамя Токі, якога багіня Віцыус прызнае няўдачай і выкідае ў старажытныя руіны. Аказваецца, яго навыкі нізкага рангу не такія ўжо і бескарысныя. Цяпер ён прагне помсты багіні, і раскрываецца яго сапраўдная натура.') WHERE media_type = 'TV' AND tmdb_id = 245285;
UPDATE entry SET title_be = COALESCE(title_be, 'Васіліск'), overview_be = COALESCE(overview_be, 'Дзеянне адбываецца ў 1614 годзе. Два кланы ніндзя — Цубагакурэ з Іга і Мандзідані з Кога — б''юцца паміж сабой, каб вызначыць, хто з унукаў Такугавы Іэясу стане наступным сёгунам. Смяротнае спаборніцтва дзесяці элітных ніндзя з кожнага клана выпускае на волю шматвяковую нянавісць, якая пагражае знішчыць усялякую надзею на мір паміж імі.') WHERE media_type = 'TV' AND tmdb_id = 9410;
UPDATE entry SET title_be = COALESCE(title_be, 'Злыдня 99-га ўзроўню: я, можа, і схаваны бос, але не ўладар дэманаў'), overview_be = COALESCE(overview_be, 'Гэтая студэнтка хоча толькі аднаго — спакойнага жыцця. Таму, перанарадзіўшыся Юміэлай, схаванай злыдняй з отомэ-RPG, яна зусім не ў захапленні. Усё яшчэ марачы пра спакой, яна адмаўляецца ад сваіх злыдзейскіх абавязкаў, каб жыць непрыкметна. Пакуль у ёй не прачынаецца геймерка — і яна выпадкова дасягае 99-га ўзроўню! Цяпер усе падазраюць, што яна і ёсць сумна вядомы Уладар дэманаў. Якая будучыня яе чакае?') WHERE media_type = 'TV' AND tmdb_id = 222930;
UPDATE entry SET title_be = COALESCE(title_be, 'Кроў Тройцы'), overview_be = COALESCE(overview_be, 'Шмат стагоддзяў таму Армагедон, наладжаны чалавекам, спарадзіў гнеў вампіраў. Пакуль людзі і неўміручыя змагаюцца, навісае пагроза, здольная разбурыць саму рэальнасць. Надзея — толькі на новае пакаленне паляўнічых, якія дзейнічаюць пад уладай Ватыкана. Сапраўдная бітва паміж святасцю і злом пачалася.') WHERE media_type = 'TV' AND tmdb_id = 23406;
UPDATE entry SET title_be = COALESCE(title_be, 'Дзядзька-навічок сярод авантурыстаў, якога да паўсмерці натрэніравала наймацнейшая каманда, стаў непераможным'), overview_be = COALESCE(overview_be, 'Звычайна авантурыстамі становяцца ў падлеткавым узросце. 30-гадовы Рык Гладыятар ідзе супраць плыні: ён кідае працу клерка ў гільдыі, каб стаць авантурыстам. Ён пачынае навічком рангу F, але з баявой сілай рангу S. Пасля двух гадоў жорсткіх трэніровак з наймацнейшай камандай кантынента, «Арыхалкавым кулаком», Рык пераможа кожнага, хто яго недаацэньвае!') WHERE media_type = 'TV' AND tmdb_id = 250598;
UPDATE entry SET title_be = COALESCE(title_be, 'Сінобі Ітокі'), overview_be = COALESCE(overview_be, 'Нашчадак клана ніндзя Іга трэніруецца, каб стаць сінобі, і змагаецца з варожым кланам Кога!') WHERE media_type = 'TV' AND tmdb_id = 158293;
UPDATE entry SET title_be = COALESCE(title_be, 'Ведзьма і звер'), overview_be = COALESCE(overview_be, 'Гідо — маладая жанчына, праклятая ведзьмай і вымушаная насіць у сабе цёмную таямніцу. Ашаф — высокі мужчына з ціхім голасам, з труной за спінай і таямніцамі, якія яшчэ не раскрытыя. Разам яны вандруюць па краіне, шукаючы помсты. Знешнасць бывае падманлівай, і кожны крок можа стаць для іх апошнім. Ці знойдуць нечаканыя героі помсту, якой прагнуць, у гэтым цёмным фэнтэзі, поўным прыгод?') WHERE media_type = 'TV' AND tmdb_id = 208445;
UPDATE entry SET title_be = COALESCE(title_be, 'Мой статус забойцы відавочна вышэйшы за статус героя'), overview_be = COALESCE(overview_be, 'Акіру Оду і яго аднакласнікаў прызываюць у іншы свет! Іншыя вучні пры прызыве атрымліваюць чыт-здольнасці, а Акіру дастаюцца толькі здольнасці пасрэднага «забойцы». Аднак неўзабаве яго статус пераўзыходзіць «героя» — наймацнейшую прафесію. Калі Акіра пачынае падазраваць караля, які стаіць за прызывам, яго ілжыва абвінавачваюць у злачынстве, і ён вымушаны ўцякаць.') WHERE media_type = 'TV' AND tmdb_id = 284644;
UPDATE entry SET title_be = COALESCE(title_be, 'Выгнаны прыдворны маг хоча стаць наймацнейшым'), overview_be = COALESCE(overview_be, 'Алек Ігрэт, калісьці адданы прыдворны маг, які з-за куліс падтрымліваў кронпрынца, аказваецца адкінутым і выгнаным за тое, што валодае толькі магіяй падтрымкі. Але якраз калі ён апускаецца на самае дно, ён зноў сустракае Ёрху Айзенц — былую таварышку па легендарнай камандзе «Lasting Period». Атрымаўшы запрашэнне вярнуцца ў каманду, якая калісьці ўвайшла ў гісторыю, Алек зноў бярэцца за даследаванне падзямелляў — і пачынае новы раздзел свайго жыцця!') WHERE media_type = 'TV' AND tmdb_id = 286984;
UPDATE entry SET title_be = COALESCE(title_be, 'Невыразная Касівада і выразны Оота'), overview_be = COALESCE(overview_be, 'Твар Касівады-сан — шэдэўр стаіцызму. Яе аднакласнік Оота-кун? Хадзячы выбух эмоцый, які цвёрда вырашыў парушыць яе спакой сваімі неверагоднымі выхадкамі. (Спойлер: не атрымліваецца.) Але паміж яго няўдалымі сюрпрызамі і яе таемнымі ўсмешкамі гэтыя поўныя супрацьлегласці, здаецца, падабаюцца адно аднаму! Рамантычная камедыя, у якой каханне гаворыць гучней за выразы твару.') WHERE media_type = 'TV' AND tmdb_id = 286388;
UPDATE entry SET title_be = COALESCE(title_be, 'Сола-кемпінг на дваіх'), overview_be = COALESCE(overview_be, 'Гэн Кінакура проста хацеў атрымліваць асалоду ад спакойных паходаў у адзіночку — без клопатаў і праблем. І тут з''яўляецца Сідзуку Кусана — недасведчаная, але поўная энтузіязму пачаткоўка, якая (літаральна) урываецца на яго стаянку. Цяпер незадаволенаму аматару прыроды даводзіцца вучыць яе азам. Смех, няўдачы і кранальныя моманты чакаюць у гэтай прыгодзе на дваіх пад зоркамі!') WHERE media_type = 'TV' AND tmdb_id = 281044;
UPDATE entry SET title_be = COALESCE(title_be, 'Мой дар 9999-га ўзроўню «Бязмежная гача»: мне здрадзілі ў глыбіні падзямелля, і я іду помсціць!'), overview_be = COALESCE(overview_be, 'У старажытныя часы Бог стварыў дзевяць рас. Людзі былі найслабейшай з іх, і з іх больш за ўсіх кпілі. Лайту, хлопчыку-чалавеку, пашчасціла: яго запрасілі ў каманду з прадстаўнікоў усіх дзевяці рас пад назвай «Збор рас». Нейкі час ён быў шчаслівы ў камандзе, але гэта аказалася кароткім сном. Яго надзеі растапталі таварышы, якія здрадзілі яму ў найвялікшым і найжахлівейшым падзямеллі — «Бездані». Выжыўшы ў адзіночку на дне Бездані, Лайт спасцігае сапраўдны сэнс свайго дару — «Бязмежнай гачы». Ён падымецца з найглыбейшага адчаю і пабудуе ўласную імперыю наймацнейшых.') WHERE media_type = 'TV' AND tmdb_id = 278635;
UPDATE entry SET title_be = COALESCE(title_be, 'Новае жыццё геніяльнага лекара ў цені'), overview_be = COALESCE(overview_be, 'Выгнаны як «бескарысны», Зенас, лекар-самавук з трушчоб, ператварае адчай у выклік і адкрывае таемную клініку ў цені горада. Сваёй неліцэнзаванай, але непераўзыдзенай магіяй ён лечыць, суцяшае і выпраўляе несправядлівасць, паціху становячыся легендай. Але яго сіла расце, і на яе звяртае ўвагу нават каралеўскі палац. Ці здолее ён насуперак усяму ацаліць свет, які яго адкінуў?') WHERE media_type = 'TV' AND tmdb_id = 276253;
UPDATE entry SET title_be = COALESCE(title_be, 'Аля часам хавае свае пачуцці па-руску'), overview_be = COALESCE(overview_be, 'Аля — новая вучаніца, якая перавялася ў школу і карыстаецца папулярнасцю: яна часта трымаецца халодна і пры гэтым атрымлівае высокія адзнакі. Яна не звяртае ўвагі на свайго аднакласніка-батаніка Кудзэ Масаціку — хіба што час ад часу кідае яму якую-небудзь гуллівую фразу па-руску. Яна і не здагадваецца, што Кудзэ разумее рускую мову, хоць і робіць выгляд, што не. Паглядзім, куды завядзе іх гэтая дзівакаватая гісторыя кахання!') WHERE media_type = 'TV' AND tmdb_id = 235758;
UPDATE entry SET title_be = COALESCE(title_be, 'Выгнаны былы герой жыве як хоча'), overview_be = COALESCE(overview_be, 'Алена выганяюць з герцагства Вестфельт з-за нізкага ўзроўню і адсутнасці Дару ад багоў — і здаецца, што ўсё страчана. Але Ален памятае сваё мінулае жыццё, у якім быў героем, і бачыць у гэтым павароце лёсу шчаслівы выпадак: нарэшце можна жыць так, як хочацца! Гэты кароткі спакой заканчваецца, калі Ален ратуе сваю былую нявесту, — і для выгнанага былога героя пачынаецца новая сага.') WHERE media_type = 'TV' AND tmdb_id = 229108;
UPDATE entry SET title_be = COALESCE(title_be, 'Няправільны спосаб выкарыстання лекавай магіі'), overview_be = COALESCE(overview_be, 'Звычайная дарога са школы дадому ператвараецца для Усата ў эпічнае падарожжа. Раптам апынуўшыся ў іншым свеце разам з двума іншымі вучнямі, Усата даведваецца, што яго прызвалі выпадкова. Але ўсё мяняецца, калі ў яго выяўляецца ўнікальны талент да лекавай магіі! Цяпер ён трэніруецца па-за межамі чалавечых магчымасцей і з дапамогай здольнасці да самаацалення набывае неверагодную сілу і непераўзыдзеную вынослівасць.') WHERE media_type = 'TV' AND tmdb_id = 131365;
UPDATE entry SET title_be = COALESCE(title_be, 'Харымія'), overview_be = COALESCE(overview_be, 'Таемнае жыццё — адзінае, што іх аб''ядноўвае. У школе Хоры — узорная і бездакорная душа кампаніі, але насамрэч яна рэзкаватая дамаседка. А Міямура пад панурай знешнасцю хавае пяшчотнае сэрца — а яшчэ пірсінг і татуіроўкі. Выпадкова сустрэўшыся, яны паказваюць адно аднаму бок, якога ніхто ніколі не бачыў. Ці вырасце з гэтага нешта новае?') WHERE media_type = 'TV' AND tmdb_id = 110070;
UPDATE entry SET title_be = COALESCE(title_be, 'Бяссонніца пасля школы'), overview_be = COALESCE(overview_be, 'Ганта Накамі — старшакласнік, які пакутуе на бяссонніцу. Ён знаёміцца з Ісакі Магары — дзяўчынай з такой самай праблемай. Паміж імі ўзнікаюць адносіны: яны дзеляць адну таямніцу і адсыпаюцца ў закінутай школьнай абсерваторыі.') WHERE media_type = 'TV' AND tmdb_id = 155440;
UPDATE entry SET title_be = COALESCE(title_be, 'Тваё імя'), overview_be = COALESCE(overview_be, 'Старшакласнікі Міцуха і Такі — зусім незнаёмыя людзі, кожны з якіх жыве сваім жыццём. Але аднойчы ўначы яны раптам мяняюцца месцамі: Міцуха прачынаецца ў целе Такі, а ён — у яе. Гэтая дзіўная з''ява паўтараецца зноў і зноў без усялякай заканамернасці, і абодвум даводзіцца падладжваць свае жыцці адно пад аднаго.') WHERE media_type = 'MOVIE' AND tmdb_id = 372058;
UPDATE entry SET title_be = COALESCE(title_be, 'У гэтай кампаніі ёсць той, хто мне падабаецца'), overview_be = COALESCE(overview_be, 'Юі Міцуя і Масугу Татэісі — не проста калегі: яны па вушы закаханыя адно ў аднаго. Ад яго гатоўнасці дапамагчы і сціпласці ў яе кружыцца галава, а ад яе мілавіднасці ён усміхаецца, як дурань. Праблема ў тым, што яны спрабуюць трымаць свае новыя адносіны ў таямніцы, каб пазбегнуць няёмкасці на працы. Але яны так цягнуцца адно да аднаго, што з кожным днём у офісе рызыкуюць выдаць свой маленькі сакрэт.') WHERE media_type = 'TV' AND tmdb_id = 262141;
UPDATE entry SET title_be = COALESCE(title_be, '365 дзён да вяселля'), overview_be = COALESCE(overview_be, 'Такуя і Рыка працуюць у адным турыстычным агенцтве ў Токіа; абое — шчаслівыя інтраверты і жывуць адны. Але ў наступным годзе іх кампанія адкрывае новы філіял на Алясцы, і туды адправяць супрацоўнікаў, у якіх няма мужа ці жонкі. Адчайна жадаючы пазбегнуць пераезду, яны — хоць раней амаль не размаўлялі — вырашаюць інсцэніраваць заручыны. Ці здолеюць гэтыя ціхія калегі стаць пераканаўчай парай?') WHERE media_type = 'TV' AND tmdb_id = 230189;
UPDATE entry SET title_be = COALESCE(title_be, 'Унук мудраца'), overview_be = COALESCE(overview_be, 'Малады чалавек перанараджаецца ў іншым свеце, дзе яго немаўлём усынаўляе герой Мерлін Уолфард і дае яму імя Сін. Да 15-годдзя Сін, вучачыся ў Мерліна, набывае самую розную сілу, але аднаго прыёмны дзядуля яму так і не даў — ані кроплі здаровага сэнсу.') WHERE media_type = 'TV' AND tmdb_id = 85844;
UPDATE entry SET title_be = COALESCE(title_be, 'Мы з табой поўныя супрацьлегласці'), overview_be = COALESCE(overview_be, 'Судзукі — закаханая старшакласніца, але хлопец, які ёй падабаецца, зусім на яе не падобны! Яна вясёлая, таварыская і заўсёды стараецца быць як усе, а яе аднакласнік Юсукэ Тані стрыманы, ціхі, і яму, здаецца, усё роўна, што пра яго думаюць. Ці здолее Судзукі перамагчы свае трывогі і запрасіць яго на спатканне — ці высветліцца, што супрацьлегласці насамрэч не прыцягваюцца?') WHERE media_type = 'TV' AND tmdb_id = 278043;
UPDATE entry SET title_be = COALESCE(title_be, 'Дэманы царства ценяў'), overview_be = COALESCE(overview_be, 'Юру, малады паляўнічы, жыве ў маленькай вёсцы глыбока ў гарах: палюе на дзічыну і вядзе сціплае жыццё разам з Асой, сваёй малодшай сястрой-блізняткай. Іх мірнае жыццё руйнуецца, калі неба прарэзвае рык дракона. Якія таямніцы хавае іх вёска? Які лёс іх чакае?') WHERE media_type = 'TV' AND tmdb_id = 260463;
UPDATE entry SET title_be = COALESCE(title_be, 'Чорны факел'), overview_be = COALESCE(overview_be, 'Дзіро Адзума — не звычайны старшакласнік. Нашчадак ніндзя, навучаны старажытнаму ваярскаму мастацтву сінобі, Дзіро яшчэ і ўмее размаўляць з жывёламі. Пасля таямнічай сустрэчы з параненым катом па імені Раго Дзіро даведваецца, што гэты кот насамрэч — легендарная Чорная зорка пагібелі! Разам з Бюро шпіянажу яны адбіваюцца ад полчышчаў манонокэ, якія толькі і чакаюць выпадку скарыстацца сіламі Раго.') WHERE media_type = 'TV' AND tmdb_id = 285993;
UPDATE entry SET title_be = COALESCE(title_be, 'Нябачнае каханне пад ясным начным небам'), overview_be = COALESCE(overview_be, 'Какэру Сарана, ціхі першакурснік, які пазбягае людзей, сустракае Кохару Фуюцукі — сляпую дзяўчыну, якая глядзіць на свет з ціхай светлай радасцю. Калі яна кажа: «Хачу калі-небудзь убачыць феерверк», — нешта ў Какэру мяняецца. Збліжаючыся праз дробязі і агульную самоту, ён шукае спосаб здзейсніць яе жаданне.') WHERE media_type = 'TV' AND tmdb_id = 309974;
UPDATE entry SET title_be = COALESCE(title_be, 'Вотакой: атаку цяжка кахаць'), overview_be = COALESCE(overview_be, 'Нарумі — офісная супрацоўніца, якая хавае, што яна фанатка яоя. Змяніўшы працу, яна зноў сустракае Хіратаку — сябра дзяцінства, прывабнага і здольнага, але заўзятага гейма-атаку. Яны вырашаюць пакуль што паспрабаваць сустракацца, але абое — атаку і вельмі няўклюдныя, таму сур''ёзныя рамантычныя адносіны даюцца ім даволі цяжка…') WHERE media_type = 'TV' AND tmdb_id = 78457;
UPDATE entry SET title_be = COALESCE(title_be, 'Бачыць, чуць, кахаць'), overview_be = COALESCE(overview_be, 'Мангака Сіндзі Ідзумота дамогся экранізацыі сваёй мангі. Ён мусіў бы святкаваць, але ён слепне, яго серыю мангі закрылі, і ён больш не можа клапаціцца пра бабулю. Застаўшыся зусім адзін, Сіндзі прымае страшнае рашэнне — скочыць з балкона. Яго ратуе Хібікі Аіда, яго глухая прыхільніца, — і яны пачынаюць незвычайнае жыццё разам.') WHERE media_type = 'MOVIE' AND tmdb_id = 1124341;
UPDATE entry SET title_be = COALESCE(title_be, 'Запячатвальнік'), overview_be = COALESCE(overview_be, 'У гэтым свеце існуюць дэманічныя мячы. Той, хто валодае такім мячом, страчвае ўласную волю: ён прагне чалавечай крыві і забівае ўсіх без разбору. Запячатвальнік — той, хто шукае клінкі, якія авалодваюць людзьмі, і запячатвае іх сваімі ножнамі.') WHERE media_type = 'TV' AND tmdb_id = 155168;
UPDATE entry SET title_be = COALESCE(title_be, 'Закаханыя'), overview_be = COALESCE(overview_be, 'Аой Міура нарадзіўся і вырас у прэфектуры Таяма. Ён нерашучы па характары і не любіць лета. У школе ён быў галоўнай надзеяй каманды па плаванні, а цяпер працуе памочнікам у невялікім архітэктурным бюро ў Токіа. Аднойчы летам ён сустракае сяброўку дзяцінства і сваё першае каханне — Акары Сэрыдзаву. У школьныя гады яны кожны дзень бавілі час разам — аж да вечара феерверкаў у выпускным класе. У тую ноч Акары раптоўна знікла. Цяпер побач з Акары — мужчына, якога таксама завуць Аой.') WHERE media_type = 'TV' AND tmdb_id = 64038;
UPDATE entry SET title_be = COALESCE(title_be, 'Мая маладосць'), overview_be = COALESCE(overview_be, 'Гісторыя Сон У Хэ і Сон Джэ Ён, якія сустракаюцца зноў праз 15 гадоў; кожны з іх змагаецца і апантана жыве на сваёй уласнай сцэне.') WHERE media_type = 'TV' AND tmdb_id = 262237;
UPDATE entry SET title_be = COALESCE(title_be, 'Адважная грамадзянка'), overview_be = COALESCE(overview_be, 'Выключаная з боксу чэмпіёнка, якая цяпер працуе школьнай настаўніцай, становіцца сведкай нясцерпнага гвалту — і, надзеўшы маску, наносіць свой першы ўдар, каб аднавіць справядлівасць.') WHERE media_type = 'MOVIE' AND tmdb_id = 897160;
